export interface Item {
  type: string;
  cursed?: boolean;
  enchantment?: number;
}

/**
 * Premiums are accumulated in hundredths of a G so that percentage
 * modifiers stay exact; only the final amount is rounded.
 */
const SCALE = 100;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

export interface Customer {
  yearsWithMHPCO: number;
}

const COMPONENTS = ['rune', 'moonstone'];
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

function countsByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

export function quote(
  items: Item[],
  customer: Customer = { yearsWithMHPCO: 0 },
  contractIndex = 0,
): number {
  let base = 0;
  let itemSurcharges = 0;
  for (const item of items) {
    const itemBase = BASE_PREMIUM[item.type] * SCALE;
    base += itemBase;
    if (item.cursed) {
      itemSurcharges += itemBase / 2;
    }
    if ((item.enchantment ?? 0) >= 5) {
      itemSurcharges += (itemBase * 3) / 10;
    }
  }
  for (const [type, count] of countsByType(items)) {
    if (COMPONENTS.includes(type) && count === BLOCK_SIZE) {
      base -= (count * BASE_PREMIUM[type] - BLOCK_PREMIUM) * SCALE;
    }
  }
  const loyalty = customer.yearsWithMHPCO >= 2 ? base / 5 : 0;
  const followUp = contractIndex > 0 ? (base * 15) / 100 : 0;
  const total = base + itemSurcharges - loyalty - followUp + base / 10 + 5 * SCALE;
  return Math.ceil(total / SCALE);
}

