export class Policy {
  private remainingCap: number;

  constructor(private readonly items: Item[]) {
    this.remainingCap = 2 * insuranceSum(items);
  }

  claim(damages: Damage[]): ClaimResult {
    let payout = 0;
    for (const damage of damages) {
      const item = this.items.find((candidate) => candidate.type === damage.itemType);
      if (item === undefined) {
        throw new Error(`item not covered by the policy: ${damage.itemType}`);
      }
      const reimbursable =
        (item.enchantment ?? 0) >= 8 ? damage.amount / 2 : damage.amount;
      payout += reimbursable - DEDUCTIBLE;
    }
    payout = Math.min(payout, this.remainingCap);
    this.remainingCap -= payout;
    return { payout, remainingCap: this.remainingCap };
  }
}

