import type { Item } from './quote';

const INSURANCE_VALUE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

export function insuranceSum(items: Item[]): number {
  let sum = 0;
  for (const item of items) {
    sum += INSURANCE_VALUE[item.type];
  }
  return sum;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;

export class Policy {
  private remainingCap: number;

  constructor(private readonly items: Item[]) {
    this.remainingCap = 2 * insuranceSum(items);
  }

  claim(damages: Damage[]): ClaimResult {
    const available = [...this.items];
    let payout = 0;
    for (const damage of damages) {
      if (damage.amount < 0) {
        throw new Error(`negative damage amount: ${damage.amount}`);
      }
      const index = available.findIndex((candidate) => candidate.type === damage.itemType);
      if (index === -1) {
        throw new Error(`item not covered by the policy: ${damage.itemType}`);
      }
      const [item] = available.splice(index, 1);
      const reimbursable =
        (item.enchantment ?? 0) >= 8 ? damage.amount / 2 : damage.amount;
      payout += reimbursable - DEDUCTIBLE;
    }
    payout = Math.min(Math.floor(payout), this.remainingCap);
    this.remainingCap -= payout;
    return { payout, remainingCap: this.remainingCap };
  }
}

